import React, { useEffect, useState } from "react";
import GitHubCalendar from "react-github-calendar";
import { Row } from "react-bootstrap";

function Github() {
  const [sizes, setSizes] = useState({ blockSize: 30, blockMargin: 8, fontSize: 16 });

  useEffect(() => {
    function update() {
      const w = window.innerWidth;
      if (w < 480) setSizes({ blockSize: 12, blockMargin: 4, fontSize: 10 });
      else if (w < 768) setSizes({ blockSize: 16, blockMargin: 6, fontSize: 12 });
      else if (w < 1024) setSizes({ blockSize: 20, blockMargin: 6, fontSize: 14 });
      else setSizes({ blockSize: 30, blockMargin: 8, fontSize: 16 });
    }

    update();
    window.addEventListener("resize", update);
    return () => window.removeEventListener("resize", update);
  }, []);

  return (
    <Row
      style={{
        justifyContent: "center",
        paddingBottom: "10px",
        color: "white",
      }}
    >
      <h1 className="project-heading pb-4" style={{ paddingBottom: "20px" }}>
        Days I <strong className="purple">Code</strong>
      </h1>

      <div className="calendar-wrapper" style={{ width: "100%", overflowX: "auto", padding: "0 8px" }}>
        <GitHubCalendar
          username="zeeshanshaikh-dev"
          blockSize={sizes.blockSize}
          blockMargin={sizes.blockMargin}
          color="#c084f5"
          fontSize={sizes.fontSize}
        />
      </div>
    </Row>
  );
}

export default Github;
